shellCommands.command:
/bin/bash -lc "cat <<'EOF' > lib/products.ts
import { cacheLife, cacheTag } from 'next/cache';
import { getAllProducts } from './db';

type Product = {
  id: number;
  name: string;
  price: number;
};

export async function getProducts(): Promise<Product[]> {
  'use cache';
  cacheLife('max');
  cacheTag('products');

  return getAllProducts();
}
EOF"

/bin/bash -lc "cat <<'EOF' > app/globals.css
:root {
  --color-sand: #f6f1e8;
  --color-ink: #1f2937;
  --color-muted: #6b7280;
  --color-panel: #fffdf8;
  --color-line: #e5e0d7;
  --color-accent: #117a65;
  --color-accent-dark: #0f5f4f;
  --color-accent-soft: #e7f3ef;
  --shadow-panel: 0 18px 40px rgba(15, 23, 42, 0.12);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--color-ink);
  font-family: var(--font-body), 'Segoe UI', sans-serif;
  background:
    radial-gradient(circle at 12% 12%, rgba(17, 122, 101, 0.16), transparent 48%),
    radial-gradient(circle at 82% 18%, rgba(248, 152, 94, 0.14), transparent 44%),
    var(--color-sand);
}

main {
  display: block;
}

.catalog-shell {
  max-width: 1160px;
  margin: 0 auto;
  padding: 36px 24px 64px;
}

.catalog-panel {
  background: var(--color-panel);
  border: 1px solid var(--color-line);
  border-radius: 24px;
  padding: 28px;
  box-shadow: var(--shadow-panel);
  animation: fadeUp 0.6s ease-out both;
}

.catalog-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.catalog-eyebrow {
  margin: 0 0 8px;
  font-size: 12px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-muted);
}

.catalog-title {
  margin: 0;
  font-size: 32px;
  font-weight: 600;
  font-family: var(--font-display), var(--font-body), sans-serif;
}

.catalog-subtitle {
  margin: 12px 0 0;
  color: var(--color-muted);
  max-width: 520px;
  line-height: 1.6;
}

.sync-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.sync-button {
  border: none;
  background: var(--color-accent);
  color: white;
  font-weight: 600;
  font-size: 14px;
  padding: 12px 18px;
  border-radius: 999px;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
  box-shadow: 0 12px 20px rgba(17, 122, 101, 0.22);
}

.sync-button:hover {
  transform: translateY(-1px);
  background: var(--color-accent-dark);
}

.sync-note {
  font-size: 12px;
  color: var(--color-muted);
}

.catalog-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 24px 0 18px;
}

.meta-pill {
  background: var(--color-accent-soft);
  color: var(--color-accent-dark);
  border-radius: 999px;
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 600;
}

.catalog-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.catalog-table thead th {
  text-align: left;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-muted);
  padding: 12px 10px;
  border-bottom: 1px solid var(--color-line);
}

.catalog-table tbody td {
  padding: 14px 10px;
  border-bottom: 1px solid var(--color-line);
}

.catalog-table tbody tr:hover {
  background: rgba(17, 122, 101, 0.06);
}

.availability-chip {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  background: rgba(17, 122, 101, 0.12);
  color: var(--color-accent-dark);
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 720px) {
  .catalog-shell {
    padding: 24px 16px 48px;
  }

  .catalog-panel {
    padding: 20px;
  }

  .catalog-title {
    font-size: 26px;
  }

  .catalog-table thead {
    display: none;
  }

  .catalog-table,
  .catalog-table tbody,
  .catalog-table tr,
  .catalog-table td {
    display: block;
    width: 100%;
  }

  .catalog-table tr {
    padding: 12px 0;
    border-bottom: 1px solid var(--color-line);
  }

  .catalog-table tbody td {
    border: none;
    padding: 6px 0;
  }

  .catalog-table tbody td::before {
    content: attr(data-label);
    display: block;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--color-muted);
    margin-bottom: 4px;
  }
}
EOF"
